B.bTC=s(["order","kaise","karna","mangwana","kharidna"],t.s)
B.bvI=s(["order_kaise","order kaise kare",'Order karna bahut aasan hai \ud83d\ude0a Bas mujhe yahin chat mein dawa ka naam likh dijiye \u2014 jaise "DB Boost chahiye". Main price bata ke poora order khud karwa dunga: quantity \u2192 address confirm \u2192 wallet PIN \u2014 sab yahin ho jayega. App ghumne ki zaroorat nahi \ud83d\ude4f',B.bTC],t.J)
B.bS4=s(["order","cancel","radd","wapas"],t.s)
B.bVd=s(["order_cancel","order cancel kaise kare",'Order cancel karna ho to mujhe yahin likh dijiye \u2014 "order cancel karna hai". Main staff ko turant bata dunga, wo aapka order cancel kar denge aur paisa wallet mein wapas aa jayega \ud83d\ude4f',B.bS4],t.J)
B.bU7=s(["delivery","kitne din","kab aayega","courier","time"],t.s)
B.btx=s(["delivery_time","delivery kitne din me aati hai",'Order confirm hote hi aapko expected dispatch date bata di jati hai \ud83d\udce6 Dispatch ke baad courier 2-5 din leta hai (jagah ke hisab se). Aap mujhse kabhi bhi puchh sakte hain \u2014 "mera order kahan pahucha" \u2014 main live status bata dunga \ud83d\ude9a',B.bU7],t.J)
B.bUc=s(["pin","bhool","bhul","forgot","reset","yaad nahi"],t.s)
B.btE=s(["wallet_pin_reset","wallet pin bhool gaye kya kare",'Koi baat nahi \ud83d\ude0a Wallet kholiye \u2192 "Forgot PIN" pe click kariye \u2014 aapki request staff ke paas jayegi aur wo naya PIN set karwa denge. Ya mujhe likh dijiye "staff se baat karao" \ud83d\ude4f',B.bUc],t.J)
B.bSj=s(["password","badle","change","badalna"],t.s)
B.bNV=s(["password_change","password kaise badle",'Abhi app ke andar password badalne ka option nahi hai \ud83d\ude4f Aap "staff se baat karao" likh dijiye \u2014 staff aapka password turant badal denge. (Login ID + naya password unse mil jayega)',B.bSj],t.J)
B.bIp=s(["report","upload","bhejna","photo","kaise"],t.s)
B.bOp=s(["report_upload","report kaise upload kare",'Report bhejne ke liye: \ud83c\udfe0 HOME button \u2192 dashboard me "My Reports" pe click \u2192 "+" se apni report ki photo/PDF upload kar dijiye. Doctor sahab dekh ke wahin jawab denge \u2014 aur aap mujhse bhi puchh sakte hain "meri report dekhi kya?" \ud83d\ude0a Report ki photo aap seedha is chat mein bhi bhej sakte hain \ud83d\udcf7',B.bIp],t.J)
B.bSU=s(["report","jawab","reply","kahan","milega"],t.s)
B.bH3=s(["report_reply","report ka jawab kahan milega",'Doctor sahab ka jawab "My Reports" section mein report ke neeche dikhta hai \u2705 Aur aap mujhse yahin puchh lijiye \u2014 "meri report aayi kya" \u2014 main turant bata dunga \ud83d\ude4f',B.bSU],t.J)
B.bUD=s(["address","badle","change","delivery","pata"],t.s)
B.bQr=s(["address_change","address kaise badle",'Address badalna ho to mujhe yahin likh dijiye \u2014 "address change karna hai" \u2014 main step-by-step yahin badalwa dunga \ud83d\ude0a Ya: \ud83c\udfe0 HOME \u2192 Profile tab \u2192 address edit kar lijiye \ud83d\ude4f',B.bUD],t.J)
B.bIY=s(["appointment","book","kaise","lena","karana"],t.s)
B.bMY=s(["appointment_kaise","appointment kaise book kare",'Mujhe bas likh dijiye \u2014 "appointment book karna hai" \ud83d\ude0a Main date, serial number aur time yahin book karwa dunga (booking charge wallet se PIN ke saath katega). App se karna ho to: \ud83c\udfe0 HOME \u2192 Book Appointment \ud83d\ude4f',B.bIY],t.J)
B.bMz=s(["appointment","cancel","nahi aa","radd"],t.s)
B.bO1=s(["appointment_cancel","appointment cancel kaise kare",'Mujhe likh dijiye \u2014 "appointment cancel karna hai" ya "main nahi aa paunga" \u2014 main staff ko bata dunga, wo aage ka sab handle kar lenge \ud83d\ude4f',B.bMz],t.J)
B.bPF=s(["registration","fee","kya","kitni","kyu"],t.s)
B.bPH=s(["registration_fee_kya","registration fee kya hai",'Registration fee sirf EK BAAR lagti hai \u2014 nayi ID banne par \ud83d\ude4f Yehi fee branch par aane par bhi lagti hai, online koi alag charge nahi. Ek baar jama hone ke baad jab tak aapka ilaj chalega, dubara fee NAHI lagegi \u2014 sirf dawa ka kharcha. Apni fee ka status mujhse puchhiye: "meri fee jama hui kya?"',B.bPF],t.J)
B.bGO=s(["syrup","online","kyu nahi","liquid"],t.s)
B.bL_=s(["syrup_online_kyu_nahi","syrup online kyu nahi milti","Syrup/liquid dawa courier mein leak ho sakti hai \u2014 isliye uska online order nahi hota \ud83d\ude4f Ye aapko branch ke counter se mil jayegi. Baaki tablet/capsule/powder sab online aa jata hai \ud83d\ude0a",B.bGO],t.J)
B.bSG=s(["qr","paisa","bheje","transfer","send","receive"],t.s)
B.bGh=s(["wallet_send_receive","qr se paisa kaise bheje",'Wallet kholiye \ud83d\udcb0 \u2014 "Send" se kisi dusre patient ka QR scan karke paisa bhej sakte hain, aur "Receive" se apna QR dikha ke le sakte hain. Har transaction PIN se hi hota hai \u2014 bilkul surakshit \ud83d\ude4f',B.bSG],t.J)
B.bJP=s(["offer","bonus","cashback","kaise","milega"],t.s)
B.bMi=s(["offer_kaise_mile","offer kaise milta hai",'Recharge offers wallet mein milte hain \ud83c\udf81 Jab offer chalu hota hai to "Add Money" karte waqt bonus apne aap jud jata hai. Abhi kya offer chal raha hai \u2014 ye mujhse puchh lijiye: "offer kya chal raha hai?" \ud83d\ude0a',B.bJP],t.J)
B.brC=s(["dawa","kitni bachi","khatam","tracker","din"],t.s)
B.bfn=s(["medicine_tracker","dawa kitni bachi kaise pata kare",'Aapke dashboard par har dawa ka progress bar dikhta hai \u2014 kitne din ki bachi hai \ud83d\udcca Aur mujhse yahin puchh lijiye \u2014 "meri dawa kitne din chalegi?" \u2014 main turant bata dunga. Dawa khatam hone se pehle main khud bhi yaad dila deta hoon \ud83d\ude0a',B.brC],t.J)
B.bO4=s(["bill","kahan","dekhe","invoice"],t.s)
B.bgV=s(["bill_kahan","bill kahan dekhe",'Saare bill: \ud83c\udfe0 HOME \u2192 "My Bills" mein hain \ud83e\uddfe Aakhri bill mujhse bhi puchh sakte hain \u2014 "mera last bill kitne ka tha?" \ud83d\ude0a',B.bO4],t.J)
B.bMy=s(["order","track","kahan","delivery","status"],t.s)
B.bUT=s(["order_track","order track kaise kare",'Mujhse yahin puchh lijiye \u2014 "mera order kahan pahucha?" \u2014 main live status bata dunga \ud83d\ude9a App mein bhi dekh sakte hain: \ud83c\udfe0 HOME \u2192 Track Delivery \ud83d\udce6',B.bMy],t.J)
B.bw7=s(["doctor","baat","staff","sampark","contact"],t.s)
B.bS9=s(["doctor_se_baat","doctor se baat kaise kare",'Mujhe likh dijiye \u2014 "staff se baat karao" ya "doctor se baat karni hai" \u2014 main turant staff ko inform kar dunga, wo aapse yahin chat mein baat karenge \ud83d\ude4f Doctor kab baithenge ye bhi puchh sakte hain: "doctor kab aayenge?"',B.bw7],t.J)
B.bTW=s(["emergency","ambulance","108","turant","madad"],t.s)
B.bK9=s(["emergency_kya_kare","emergency me kya kare","\ud83d\udea8 Agar bahut zyada tabiyat kharab hai (seene mein dard, saans nahi aa rahi, behoshi) to sabse pehle 108 par call karein \u2014 ambulance ke liye. Mujhe yahin likh denge to main turant saare staff ko RED ALERT bhej dunga \ud83d\ude4f",B.bTW],t.J)
B.bT2=s(["app","update","naya version","install"],t.s)
B.bKq=s(["app_update","app update kaise kare",'Jab naya version aata hai to app khud bata deti hai aur download link deti hai \ud83d\ude0a Purane phone (32-bit) ke liye alag link hota hai \u2014 dono try kar lijiyega. Koi dikkat ho to "staff se baat karao" likh dijiye \ud83d\ude4f',B.bT2],t.J)
B.bIm=s(["login","nahi ho raha","id bhool","problem"],t.s)
B.bT0=s(["login_problem","login nahi ho raha kya kare",'Login ke liye aapki Patient ID (jaise DEV1234) aur password chahiye. ID bhool gaye hain to apne mobile number ke saath "staff se baat karao" likh dijiye \u2014 staff aapki ID bata denge aur password reset karwa denge \ud83d\ude4f',B.bIm],t.J)
B.bNc=s(["kya kya","kar sakte","features","madad","help"],t.s)
B.bNY=s(["ai_kya_kya","app me kya kya kar sakte hain","Aap mujhse YAHIN chat mein sab karwa sakte hain \ud83d\ude0a\n\ud83d\udc8a Dawa order + delivery tracking\n\ud83d\udcc5 Appointment booking + doctor schedule\n\ud83d\udcb0 Wallet balance, transactions, bill\n\ud83d\udccb Report bhejna + doctor ka jawab\n\ud83e\ude7a BP/sugar likhwa dijiye \u2014 file mein save\nAur app ki koi bhi jankari \u2014 bas puchh lijiye \ud83d\ude4f",B.bNc],t.J)
B.bQY=s(["refund","paisa wapas","wapas kab","cancel paisa"],t.s)
B.bHJ=s(["paisa_wapas_refund","refund kaise milta hai",'Order cancel hone par paisa apne aap wallet mein wapas aa jata hai \u2705 Aap check kar sakte hain: "mera balance kitna hai" ya "aakhri transaction dikhao". Koi paisa atka lage to "staff se baat karao" likh dijiye \u2014 turant dekh lenge \ud83d\ude4f',B.bQY],t.J)
B.bKL=s(["dawa","time","yaad","reminder","kab lena"],t.s)
B.btI=s(["dawa_time_yaad","dawa ka time yaad kaise rahe",'Aapki parchi mein doctor sahab ne jo time likha hai wahi sabse sahi hai \u2014 mujhse puchh lijiye: "dawa kab-kab leni hai?" \u2014 main parchi se bata dunga \ud83d\udc8a Dawa khatam hone se pehle main khud yaad dila deta hoon \ud83d\ude0a',B.bKL],t.J)
B.bI0=s(["number","kab aayega","line","queue","serial"],t.s)
B.bPJ=s(["queue_number","mera number kab aayega",'Aap mujhse yahin puchh sakte hain \u2014 "mera number kab aayega?" \u2014 main live batata hoon ki aapse pehle kitne log hain \ud83d\ude0a Appointment ka serial number aur approx time bhi puchh sakte hain \ud83d\ude4f',B.bI0],t.J)
B.b8O=s(["sugar","bp","zyada","kam","pata chal","alert","khatra"],t.s)
B.bO6=s(["sugar_alert_kaise","sugar zyada kam ho to app ko pata chal jata hai kya","Haan bilkul \ud83d\ude0a Jab bhi aap mujhe apni sugar ya BP batate hain, main check karta hoon \u2014 reading normal se zyada ya kam lage to turant doctor/staff ko alert bhej deta hoon \ud83d\udea8, taaki aapko jaldi sahi salah mil sake \ud83d\ude4f",B.b8O],t.J)
